import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import { apiClient, unwrap, type BffResponse } from '../../services/api';
import { normalizeSearchText } from '../../utils/codeField';

export interface EmployeeLookupItem {
  id: string;
  code: string;
  fullName: string;
  isActive?: boolean;
}

type PaginatedEmployees = {
  items: EmployeeLookupItem[];
  totalCount?: number;
  total?: number;
  page: number;
  pageSize: number;
};

/** SEARCH_REMOTE — danh mục NV (`GET /hr/employees`) cho Customer.employeeCode. */
export function createEmployeeSearchConfig(): SearchInputConfig<EmployeeLookupItem> {
  return {
    api: {
      getItemKey: e => e.id,
      search: async ({ search, page, pageSize }) => {
        const qs = new URLSearchParams();
        const q = search ? normalizeSearchText(search) : '';
        if (q) qs.set('search', q);
        qs.set('isActive', 'true');
        qs.set('page', String(page));
        qs.set('pageSize', String(pageSize));
        const res = await apiClient.get<BffResponse<PaginatedEmployees>>(`/hr/employees?${qs}`);
        const data = unwrap(res);
        const items = data.items ?? [];
        const total = data.totalCount ?? data.total ?? items.length;
        const totalPages = Math.max(1, Math.ceil(total / pageSize));
        return { items, page: data.page ?? page, totalPages };
      },
    },
    display: {
      getPrimaryDisplay: e => e.code,
      getSecondaryDisplay: e => e.fullName,
      getSingleDisplay: e => `${e.code} — ${e.fullName}`,
    },
    columns: [
      { key: 'code', variant: 'badge', width: '6rem', render: e => e.code },
      { key: 'name', variant: 'primary', render: e => e.fullName },
    ],
    header: {
      columns: [
        { key: 'code', label: 'Mã NV' },
        { key: 'name', label: 'Họ tên' },
      ],
    },
    texts: { empty: 'Không tìm thấy nhân viên' },
    dropdownPortal: true,
    dropdownMatch: 'row',
    dropdownMinWidth: '22rem',
  };
}
