import React, { useMemo } from 'react';
import { SearchInput } from '@linm-soft-org/linm-web-common-components';
import {
  createCustomerSearchConfig,
  type CustomerSearchType,
} from '../../search/customerSearchConfig';
import type { CustomerListItemDto } from '../../../services/master/models';

type Props = {
  parentId?: string;
  parentCode?: string;
  parentName?: string;
  /** Lọc cha cùng loại form (Supplier → chỉ NCC / Both). */
  customerType?: string;
  excludeCustomerId?: string;
  disabled?: boolean;
  onChange: (parent: CustomerListItemDto) => void;
  onClear: () => void;
  testId?: string;
};

function toParentSearchType(customerType?: string): CustomerSearchType | undefined {
  const t = (customerType || '').trim();
  if (t === 'Customer' || t === 'Supplier' || t === 'Both' || t === 'Employee') return t;
  return undefined;
}

/** Lookup đối tượng cha — 2 ô Mã + Tên (parity CustomerSearchField / phiếu thu). */
export const CustomerParentLookupField: React.FC<Props> = ({
  parentId,
  parentCode,
  parentName,
  customerType,
  excludeCustomerId,
  disabled,
  onChange,
  onClear,
  testId,
}) => {
  const config = useMemo(
    () => createCustomerSearchConfig({
      customerType: toParentSearchType(customerType),
      excludeCustomerId,
    }),
    [customerType, excludeCustomerId],
  );

  return (
    <SearchInput
      config={config}
      value={parentId ?? ''}
      primaryDisplay={parentCode ?? ''}
      secondaryDisplay={parentName ?? ''}
      onChange={onChange}
      onClear={onClear}
      disabled={disabled}
      showLabel={false}
      placeholder="Mã đối tượng cha..."
      data-testid={testId}
    />
  );
};
